/**
 * Response headers every page and API response gets. The Content Security
 * Policy itself is generated by SvelteKit (see `csp` in vite.config.ts) so it
 * can carry a per-request nonce.
 */
export function securityHeaders(url: URL): Record<string, string> {
	return {
		'x-content-type-options': 'nosniff',
		'x-frame-options': 'DENY',
		'referrer-policy': 'strict-origin-when-cross-origin',
		'cross-origin-opener-policy': 'same-origin',
		'cross-origin-resource-policy': 'same-origin',
		'permissions-policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
		// only over HTTPS: sending it on plain HTTP is ignored by browsers anyway
		...(url.protocol === 'https:'
			? { 'strict-transport-security': 'max-age=31536000; includeSubDomains' }
			: {})
	};
}

/** The Content Security Policy directives, shared with tests. */
export const CSP_DIRECTIVES = {
	'default-src': ['self'],
	// SvelteKit adds a per-request nonce for its own inline scripts and app.html's theme script
	'script-src': ['self'],
	// server-rendered style="" attributes (e.g. the canvas) need this; inline scripts stay blocked
	'style-src': ['self', 'unsafe-inline'],
	'img-src': ['self', 'data:', 'https://avatars.githubusercontent.com'],
	'font-src': ['self', 'data:'],
	'connect-src': ['self'],
	'object-src': ['none'],
	'base-uri': ['self'],
	'form-action': ['self'],
	'frame-ancestors': ['none']
} as const;
